import Model from 'flarum/common/Model';
export default class Doorkey extends Model {
  key() {
    return Model.attribute('key').call(this);
  }
  groupId() {
    return Model.attribute('groupId').call(this);
  }
  group() {
    return Model.hasOne('group').call(this);
  }
  maxUses() {
    return Model.attribute('maxUses').call(this);
  }
  activates() {
    return Model.attribute('activates').call(this);
  }
  uses() {
    return Model.attribute('uses').call(this);
  }
  createdBy() {
    return Model.hasOne('createdBy').call(this);
  }
  apiEndpoint() {
    return '/doorkeys' + (this.exists ? `/${this.data.id}` : '');
  }
}
flarum.reg.add('fof-doorman', 'common/models/Doorkey', Doorkey);